#include <list>
#include <iostream>

int main() {
    std::list<int> lst = {1, 2, 3, 4};  // Initialize with values

    // Check if the list is empty before processing
    if (lst.empty()) {
        std::cout << "List is empty." << std::endl;
    } else {
        std::cout << "List contains elements: ";
        for (const auto& element : lst) {
            std::cout << element << " ";
        }
        std::cout << std::endl;
    }

    // Example of adding and removing elements
    lst.push_front(0);  // Efficient O(1) operation
    lst.push_back(5);
    lst.erase(std::next(lst.begin()));  // Remove the second element

    return 0;
}
